import csv
import logging

log = logging.getLogger(__name__)


def export(records, path):
    handle = open(path, "w")
    writer = csv.writer(handle)
    for record in records:
        writer.writerow([record.id, record.name])
    return path


def export_all(batches, path):
    try:
        for batch in batches:
            export(batch, path)
    except Exception:
        pass


def describe():
    return "csv exporter"
